const char *Nxt_tr(const char *text) { if(!text)return "";if(nxt.language>1)return NxtLocale_text(text); if(!nxt.language&&strcmp(text,"Music Player"))return text; for(unsigned i=0;i<sizeof(table)/sizeof(*table);i++)if(!strcmp(text,table[i].en))return table[i].vi;return text; }
SDL_Surface *Nxt_render(TTF_Font *font,const char *text,SDL_Color color) { return NxtText_render(font,Nxt_tr(text),color); }
